def check_if_any_element_has_prime_frequency(nums):
    # Helper function for prime check (returns True if n is prime)
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    # Step 1: Count frequency of each element
    freq = {}
    for num in nums:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Step 2: Check if any frequency is prime
    for count in freq.values():
        if is_prime(count):
            return True

    return False
